use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Span { # [inline] pub fn lo (self) -> BytePos { self . data () . lo } # [inline] pub fn with_lo (self , lo : BytePos) -> Span { self . data () . with_lo (lo) } # [inline] pub fn hi (self) -> BytePos { self . data () . hi } # [inline] pub fn with_hi (self , hi : BytePos) -> Span { self . data () . with_hi (hi) } # [inline] pub fn with_ctxt (self , ctxt : SyntaxContext) -> Span { self . map_ctxt (| _ | ctxt) } # [inline] pub fn is_visible (self , sm : & SourceMap) -> bool { ! self . is_dummy () && sm . is_span_accessible (self) } # [doc = " Returns whether this span originates in a foreign crate's external macro."] # [doc = ""] # [doc = " This is used to test whether a lint should not even begin to figure out whether it should"] # [doc = " be reported on the current node."] # [inline] pub fn in_external_macro (self , sm : & SourceMap) -> bool { self . ctxt () . in_external_macro (sm) } # [doc = " Returns `true` if `span` originates in a derive-macro's expansion."] pub fn in_derive_expansion (self) -> bool { matches ! (self . ctxt () . outer_expn_data () . kind , ExpnKind :: Macro (MacroKind :: Derive , _)) } # [doc = " Return whether `span` is generated by `async` or `await`."] pub fn is_from_async_await (self) -> bool { matches ! (self . ctxt () . outer_expn_data () . kind , ExpnKind :: Desugaring (DesugaringKind :: Async | DesugaringKind :: Await) ,) } # [doc = " Gate suggestions that would not be appropriate in a context the user didn't write."] pub fn can_be_used_for_suggestions (self) -> bool { ! self . from_expansion () || (self . in_derive_expansion () && self . parent_callsite () . map (| p | (p . lo () , p . hi ())) != Some ((self . lo () , self . hi ()))) } # [inline] pub fn with_root_ctxt (lo : BytePos , hi : BytePos) -> Span { Span :: new (lo , hi , SyntaxContext :: root () , None) } # [doc = " Returns a new span representing an empty span at the beginning of this span."] # [inline] pub fn shrink_to_lo (self) -> Span { let span = self . data_untracked () ; span . with_hi (span . lo) } # [doc = " Returns a new span representing an empty span at the end of this span."] # [inline] pub fn shrink_to_hi (self) -> Span { let span = self . data_untracked () ; span . with_lo (span . hi) } # [inline] # [doc = " Returns `true` if `hi == lo`."] pub fn is_empty (self) -> bool { let span = self . data_untracked () ; span . hi == span . lo } # [doc = " Returns `self` if `self` is not the dummy span, and `other` otherwise."] pub fn substitute_dummy (self , other : Span) -> Span { if self . is_dummy () { other } else { self } } # [doc = " Returns `true` if `self` fully encloses `other`."] pub fn contains (self , other : Span) -> bool { let span = self . data () ; let other = other . data () ; span . contains (other) } # [doc = " Returns `true` if `self` touches `other`."] pub fn overlaps (self , other : Span) -> bool { let span = self . data () ; let other = other . data () ; span . lo < other . hi && other . lo < span . hi } # [doc = " Returns `true` if `self` touches or adjoins `other`."] pub fn overlaps_or_adjacent (self , other : Span) -> bool { let span = self . data () ; let other = other . data () ; span . lo <= other . hi && other . lo <= span . hi } # [doc = " Returns `true` if the spans are equal with regards to the source text."] # [doc = ""] # [doc = " Use this instead of `==` when either span could be generated code,"] # [doc = " and you only care that they point to the same bytes of source text."] pub fn source_equal (self , other : Span) -> bool { let span = self . data () ; let other = other . data () ; span . lo == other . lo && span . hi == other . hi } # [doc = " Returns `Some(span)`, where the start is trimmed by the end of `other`."] pub fn trim_start (self , other : Span) -> Option < Span > { let span = self . data () ; let other = other . data () ; if span . hi > other . hi { Some (span . with_lo (cmp :: max (span . lo , other . hi))) } else { None } } # [doc = " Returns `Some(span)`, where the end is trimmed by the start of `other`."] pub fn trim_end (self , other : Span) -> Option < Span > { let span = self . data () ; let other = other . data () ; if span . lo < other . lo { Some (span . with_hi (cmp :: min (span . hi , other . lo))) } else { None } } # [doc = " Returns the source span -- this is either the supplied span, or the span for"] # [doc = " the macro callsite that expanded to it."] pub fn source_callsite (self) -> Span { let ctxt = self . ctxt () ; if ! ctxt . is_root () { ctxt . outer_expn_data () . call_site . source_callsite () } else { self } } # [doc = " Returns the call-site span of the last macro expansion which produced this `Span`."] # [doc = " (see [`ExpnData::call_site`]). Returns `None` if this is not an expansion."] pub fn parent_callsite (self) -> Option < Span > { let ctxt = self . ctxt () ; (! ctxt . is_root ()) . then (| | ctxt . outer_expn_data () . call_site) } # [doc = " Find the first ancestor span that's contained within `outer`."] # [doc = ""] # [doc = " This method traverses the macro expansion ancestors until it finds the first span"] # [doc = " that's contained within `outer`."] # [doc = ""] # [doc = " The span returned by this method may have a different [`SyntaxContext`] than `outer`."] # [doc = " If you need to extend the span, use [`find_ancestor_inside_same_ctxt`] instead,"] # [doc = " because joining spans with different syntax contexts can create unexpected results."] # [doc = ""] # [doc = " This is used to find the span of the macro call when a parent expr span, i.e. `outer`, is known."] # [doc = ""] # [doc = " [`find_ancestor_inside_same_ctxt`]: Self::find_ancestor_inside_same_ctxt"] pub fn find_ancestor_inside (mut self , outer : Span) -> Option < Span > { while ! outer . contains (self) { self = self . parent_callsite () ? ; } Some (self) } # [doc = " Find the first ancestor span with the same [`SyntaxContext`] as `other`."] # [doc = ""] # [doc = " This method traverses the macro expansion ancestors until it finds a span"] # [doc = " that has the same [`SyntaxContext`] as `other`."] # [doc = ""] # [doc = " Like [`find_ancestor_inside_same_ctxt`], but specifically for when spans might not"] # [doc = " overlap. Take care when using this, and prefer [`find_ancestor_inside`] or"] # [doc = " [`find_ancestor_inside_same_ctxt`] when you know that the spans are nested (modulo"] # [doc = " macro expansion)."] # [doc = ""] # [doc = " [`find_ancestor_inside`]: Self::find_ancestor_inside"] # [doc = " [`find_ancestor_inside_same_ctxt`]: Self::find_ancestor_inside_same_ctxt"] pub fn find_ancestor_in_same_ctxt (mut self , other : Span) -> Option < Span > { while ! self . eq_ctxt (other) { self = self . parent_callsite () ? ; } Some (self) } # [doc = " Find the first ancestor span that's contained within `outer` and"] # [doc = " has the same [`SyntaxContext`] as `outer`."] # [doc = ""] # [doc = " This method traverses the macro expansion ancestors until it finds a span"] # [doc = " that is both contained within `outer` and has the same [`SyntaxContext`] as `outer`."] # [doc = ""] # [doc = " This method is the combination of [`find_ancestor_inside`] and"] # [doc = " [`find_ancestor_in_same_ctxt`] and should be preferred when extending the returned span."] # [doc = " If you do not need to modify the span, use [`find_ancestor_inside`] instead."] # [doc = ""] # [doc = " [`find_ancestor_inside`]: Self::find_ancestor_inside"] # [doc = " [`find_ancestor_in_same_ctxt`]: Self::find_ancestor_in_same_ctxt"] pub fn find_ancestor_inside_same_ctxt (mut self , outer : Span) -> Option < Span > { while ! outer . contains (self) || ! self . eq_ctxt (outer) { self = self . parent_callsite () ? ; } Some (self) } # [doc = " Find the first ancestor span that does not come from an external macro."] # [doc = ""] # [doc = " This method traverses the macro expansion ancestors until it finds a span"] # [doc = " that is either from user-written code or from a local macro (defined in the current crate)."] # [doc = ""] # [doc = " External macros are those defined in dependencies or the standard library."] # [doc = " This method is useful for reporting errors in user-controllable code and avoiding"] # [doc = " diagnostics inside external macros."] # [doc = ""] # [doc = " # See also"] # [doc = ""] # [doc = " - [`Self::find_ancestor_not_from_macro`]"] # [doc = " - [`Self::in_external_macro`]"] pub fn find_ancestor_not_from_extern_macro (mut self , sm : & SourceMap) -> Option < Span > { while self . in_external_macro (sm) { self = self . parent_callsite () ? ; } Some (self) } # [doc = " Find the first ancestor span that does not come from any macro expansion."] # [doc = ""] # [doc = " This method traverses the macro expansion ancestors until it finds a span"] # [doc = " that originates from user-written code rather than any macro-generated code."] # [doc = ""] # [doc = " This method is useful for reporting errors at the exact location users wrote code"] # [doc = " and providing suggestions at directly editable locations."] # [doc = ""] # [doc = " # See also"] # [doc = ""] # [doc = " - [`Self::find_ancestor_not_from_extern_macro`]"] # [doc = " - [`Span::from_expansion`]"] pub fn find_ancestor_not_from_macro (mut self) -> Option < Span > { while self . from_expansion () { self = self . parent_callsite () ? ; } Some (self) } # [doc = " Edition of the crate from which this span came."] pub fn edition (self) -> edition :: Edition { self . ctxt () . edition () } # [doc = " Is this edition 2015?"] # [inline] pub fn is_rust_2015 (self) -> bool { self . edition () . is_rust_2015 () } # [doc = " Are we allowed to use features from the Rust 2018 edition?"] # [inline] pub fn at_least_rust_2018 (self) -> bool { self . edition () . at_least_rust_2018 () } # [doc = " Are we allowed to use features from the Rust 2021 edition?"] # [inline] pub fn at_least_rust_2021 (self) -> bool { self . edition () . at_least_rust_2021 () } # [doc = " Are we allowed to use features from the Rust 2024 edition?"] # [inline] pub fn at_least_rust_2024 (self) -> bool { self . edition () . at_least_rust_2024 () } # [doc = " Returns the source callee."] # [doc = ""] # [doc = " Returns `None` if the supplied span has no expansion trace,"] # [doc = " else returns the `ExpnData` for the macro definition"] # [doc = " corresponding to the source callsite."] pub fn source_callee (self) -> Option < ExpnData > { let mut ctxt = self . ctxt () ; let mut opt_expn_data = None ; while ! ctxt . is_root () { let expn_data = ctxt . outer_expn_data () ; ctxt = expn_data . call_site . ctxt () ; opt_expn_data = Some (expn_data) ; } opt_expn_data } # [doc = " Checks if a span is \"internal\" to a macro in which `#[unstable]`"] # [doc = " items can be used (that is, a macro marked with"] # [doc = " `#[allow_internal_unstable]`)."] pub fn allows_unstable (self , feature : Symbol) -> bool { self . ctxt () . outer_expn_data () . allow_internal_unstable . is_some_and (| features | features . contains (& feature)) } # [doc = " Checks if this span arises from a compiler desugaring of kind `kind`."] pub fn is_desugaring (self , kind : DesugaringKind) -> bool { match self . ctxt () . outer_expn_data () . kind { ExpnKind :: Desugaring (k) => k == kind , _ => false , } } # [doc = " Returns the compiler desugaring that created this span, or `None`"] # [doc = " if this span is not from a desugaring."] pub fn desugaring_kind (self) -> Option < DesugaringKind > { match self . ctxt () . outer_expn_data () . kind { ExpnKind :: Desugaring (k) => Some (k) , _ => None , } } # [doc = " Checks if a span is \"internal\" to a macro in which `unsafe`"] # [doc = " can be used without triggering the `unsafe_code` lint."] # [doc = " (that is, a macro marked with `#[allow_internal_unsafe]`)."] pub fn allows_unsafe (self) -> bool { self . ctxt () . outer_expn_data () . allow_internal_unsafe } pub fn macro_backtrace (mut self) -> impl Iterator < Item = ExpnData > { let mut prev_span = DUMMY_SP ; iter :: from_fn (move | | { loop { let ctxt = self . ctxt () ; if ctxt . is_root () { return None ; } let expn_data = ctxt . outer_expn_data () ; let is_recursive = expn_data . call_site . source_equal (prev_span) ; prev_span = self ; self = expn_data . call_site ; if ! is_recursive { return Some (expn_data) ; } } }) } # [doc = " Splits a span into two composite spans around a certain position."] pub fn split_at (self , pos : u32) -> (Span , Span) { let len = self . hi () . 0 - self . lo () . 0 ; debug_assert ! (pos <= len) ; let split_pos = BytePos (self . lo () . 0 + pos) ; (Span :: new (self . lo () , split_pos , self . ctxt () , self . parent ()) , Span :: new (split_pos , self . hi () , self . ctxt () , self . parent ()) ,) } # [doc = " Check if you can select metavar spans for the given spans to get matching contexts."] fn try_metavars (a : SpanData , b : SpanData , a_orig : Span , b_orig : Span) -> (SpanData , SpanData) { match with_metavar_spans (| mspans | (mspans . get (a_orig) , mspans . get (b_orig))) { (None , None) => { } (Some (meta_a) , None) => { let meta_a = meta_a . data () ; if meta_a . ctxt == b . ctxt { return (meta_a , b) ; } } (None , Some (meta_b)) => { let meta_b = meta_b . data () ; if a . ctxt == meta_b . ctxt { return (a , meta_b) ; } } (Some (meta_a) , Some (meta_b)) => { let meta_b = meta_b . data () ; if a . ctxt == meta_b . ctxt { return (a , meta_b) ; } let meta_a = meta_a . data () ; if meta_a . ctxt == b . ctxt { return (meta_a , b) ; } else if meta_a . ctxt == meta_b . ctxt { return (meta_a , meta_b) ; } } } (a , b) } # [doc = " Prepare two spans to a combine operation like `to` or `between`."] fn prepare_to_combine (a_orig : Span , b_orig : Span ,) -> Result < (SpanData , SpanData , Option < LocalDefId >) , Span > { let (a , b) = (a_orig . data () , b_orig . data ()) ; if a . ctxt == b . ctxt { return Ok ((a , b , if a . parent == b . parent { a . parent } else { None })) ; } let (a , b) = Span :: try_metavars (a , b , a_orig , b_orig) ; if a . ctxt == b . ctxt { return Ok ((a , b , if a . parent == b . parent { a . parent } else { None })) ; } let a_is_callsite = a . ctxt . is_root () || a . ctxt == b . span () . source_callsite () . ctxt () ; Err (if a_is_callsite { b_orig } else { a_orig }) } # [doc = " This span, but in a larger context, may switch to the metavariable span if suitable."] pub fn with_neighbor (self , neighbor : Span) -> Span { match Span :: prepare_to_combine (self , neighbor) { Ok ((this , ..)) => this . span () , Err (_) => self , } } # [doc = " Returns a `Span` that would enclose both `self` and `end`."] # [doc = ""] # [doc = " Note that this can also be used to extend the span \"backwards\":"] # [doc = " `start.to(end)` and `end.to(start)` return the same `Span`."] # [doc = ""] # [doc = " ```text"] # [doc = "     ____             ___"] # [doc = "     self lorem ipsum end"] # [doc = "     ^^^^^^^^^^^^^^^^^^^^"] # [doc = " ```"] pub fn to (self , end : Span) -> Span { match Span :: prepare_to_combine (self , end) { Ok ((from , to , parent)) => { Span :: new (cmp :: min (from . lo , to . lo) , cmp :: max (from . hi , to . hi) , from . ctxt , parent) } Err (fallback) => fallback , } } # [doc = " Returns a `Span` between the end of `self` to the beginning of `end`."] # [doc = ""] # [doc = " ```text"] # [doc = "     ____             ___"] # [doc = "     self lorem ipsum end"] # [doc = "         ^^^^^^^^^^^^^"] # [doc = " ```"] pub fn between (self , end : Span) -> Span { match Span :: prepare_to_combine (self , end) { Ok ((from , to , parent)) => { Span :: new (cmp :: min (from . hi , to . hi) , cmp :: max (from . lo , to . lo) , from . ctxt , parent) } Err (fallback) => fallback , } } # [doc = " Returns a `Span` from the beginning of `self` until the beginning of `end`."] # [doc = ""] # [doc = " ```text"] # [doc = "     ____             ___"] # [doc = "     self lorem ipsum end"] # [doc = "     ^^^^^^^^^^^^^^^^^"] # [doc = " ```"] pub fn until (self , end : Span) -> Span { match Span :: prepare_to_combine (self , end) { Ok ((from , to , parent)) => { Span :: new (cmp :: min (from . lo , to . lo) , cmp :: max (from . lo , to . lo) , from . ctxt , parent) } Err (fallback) => fallback , } } # [doc = " Returns the `Span` within the syntax context of \"within\". This is useful when"] # [doc = " \"self\" is an expansion from a macro variable, since this can be used for"] # [doc = " providing extra macro expansion context for certain errors."] # [doc = ""] # [doc = " ```text"] # [doc = " macro_rules! m {"] # [doc = "     ($ident:ident) => { ($ident,) }"] # [doc = " }"] # [doc = ""] # [doc = " m!(outer_ident);"] # [doc = " ```"] # [doc = ""] # [doc = " If \"self\" is the span of the outer_ident, and \"within\" is the span of the `($ident,)`"] # [doc = " expr, then this will return the span of the `$ident` macro variable."] pub fn within_macro (self , within : Span , sm : & SourceMap) -> Option < Span > { match Span :: prepare_to_combine (self , within) { Ok ((self_ , _ , parent)) if self_ . hi < self . lo () || self . hi () < self_ . lo && ! sm . is_imported (within) => { Some (Span :: new (self_ . lo , self_ . hi , self_ . ctxt , parent)) } _ => None , } } pub fn from_inner (self , inner : InnerSpan) -> Span { let span = self . data () ; Span :: new (span . lo + BytePos :: from_usize (inner . start) , span . lo + BytePos :: from_usize (inner . end) , span . ctxt , span . parent ,) } # [doc = " Equivalent of `Span::def_site` from the proc macro API,"] # [doc = " except that the location is taken from the `self` span."] pub fn with_def_site_ctxt (self , expn_id : ExpnId) -> Span { self . with_ctxt_from_mark (expn_id , Transparency :: Opaque) } # [doc = " Equivalent of `Span::call_site` from the proc macro API,"] # [doc = " except that the location is taken from the `self` span."] pub fn with_call_site_ctxt (self , expn_id : ExpnId) -> Span { self . with_ctxt_from_mark (expn_id , Transparency :: Transparent) } # [doc = " Equivalent of `Span::mixed_site` from the proc macro API,"] # [doc = " except that the location is taken from the `self` span."] pub fn with_mixed_site_ctxt (self , expn_id : ExpnId) -> Span { self . with_ctxt_from_mark (expn_id , Transparency :: SemiOpaque) } # [doc = " Produces a span with the same location as `self` and context produced by a macro with the"] # [doc = " given ID and transparency, assuming that macro was defined directly and not produced by"] # [doc = " some other macro (which is the case for built-in and procedural macros)."] fn with_ctxt_from_mark (self , expn_id : ExpnId , transparency : Transparency) -> Span { self . with_ctxt (SyntaxContext :: root () . apply_mark (expn_id , transparency)) } # [inline] pub fn apply_mark (self , expn_id : ExpnId , transparency : Transparency) -> Span { self . map_ctxt (| ctxt | ctxt . apply_mark (expn_id , transparency)) } # [inline] pub fn remove_mark (& mut self) -> ExpnId { let mut mark = ExpnId :: root () ; * self = self . map_ctxt (| mut ctxt | { mark = ctxt . remove_mark () ; ctxt }) ; mark } # [inline] pub fn adjust (& mut self , expn_id : ExpnId) -> Option < ExpnId > { let mut mark = None ; * self = self . map_ctxt (| mut ctxt | { mark = ctxt . adjust (expn_id) ; ctxt }) ; mark } # [inline] pub fn normalize_to_macros_2_0_and_adjust (& mut self , expn_id : ExpnId) -> Option < ExpnId > { let mut mark = None ; * self = self . map_ctxt (| mut ctxt | { mark = ctxt . normalize_to_macros_2_0_and_adjust (expn_id) ; ctxt }) ; mark } # [inline] pub fn glob_adjust (& mut self , expn_id : ExpnId , glob_span : Span) -> Option < Option < ExpnId > > { let mut mark = None ; * self = self . map_ctxt (| mut ctxt | { mark = ctxt . glob_adjust (expn_id , glob_span) ; ctxt }) ; mark } # [inline] pub fn reverse_glob_adjust (& mut self , expn_id : ExpnId , glob_span : Span ,) -> Option < Option < ExpnId > > { let mut mark = None ; * self = self . map_ctxt (| mut ctxt | { mark = ctxt . reverse_glob_adjust (expn_id , glob_span) ; ctxt }) ; mark } # [inline] pub fn normalize_to_macros_2_0 (self) -> Span { self . map_ctxt (| ctxt | ctxt . normalize_to_macros_2_0 ()) } # [inline] pub fn normalize_to_macro_rules (self) -> Span { self . map_ctxt (| ctxt | ctxt . normalize_to_macro_rules ()) } }